```cpp
#include <iostream>
#include <string>

std::string countAndSay(int n) {
    if (n == 1) return "1";
    std::string previous = countAndSay(n-1), result = "";
    int count = 1;
    for (int i = 0; i < previous.length(); ++i) {
        if (i + 1 < previous.length() && previous[i] == previous[i + 1]) {
            count++;
        } else {
            result += std::to_string(count) + previous[i];
            count = 1;
        }
    }
    return result;
}

int main() {
    for (int i = 1; i <= 5; ++i) {
        if (i > 1) std::cout << ", ";
        std::cout << countAndSay(i);
    }
    return 0;
}
```

```c++
#include <iostream>

bool isPrime(int n) {
    if(n <= 1) return false;
    if(n <= 3) return true;
    if(n % 2 == 0 || n % 3 == 0) return false;
    for(int i = 5; i * i <= n; i += 6)
        if(n % i == 0 || n % (i + 2) == 0) 
            return false;
    return true;
}

int main() {
    int count = 0;
    for(int num = 2; count < 10; ++num) {
        if(isPrime(num)) {
            std::cout << num << (count < 9 ? ", " : "");
            ++count;
        }
    }
    return 0;
}
