```cpp
#include <iostream>
using namespace std;

long binomialCoefficient(int n, int k) {
    long res = 1;
    if (k > n - k)
        k = n - k;
    for (int i = 0; i < k; ++i) {
        res *= (n - i);
        res /= (i + 1);
    }
    return res;
}

int main() {
    for (int n = 1; n <= 10; ++n) {
        cout << binomialCoefficient(2 * n, n) / (n + 1) << " ";
    }
    return 0;
}
```

