int factorial(int n) {
    return (n == 0 || n == 1) ? 1 : n * factorial(n - 1);
}

bool isSpecialNumber(int number) {
    int sum = 0, temp = number;
    while (temp > 0) {
        sum += factorial(temp % 10);
        temp /= 10;
    }
    return sum == number;
}

