int factorial(int n) {
    return (n == 0 || n == 1) ? 1 : n * factorial(n - 1);
}

bool isSpecial(int number) {
    int sum = 0, temp = number;
    while (temp > 0) {
        sum += factorial(temp % 10);
        temp /= 10;
    }
    return sum == number;
}

int main() {
    std::vector<int> specialNumbers = {1, 2, 145, 40585};
    for (int num : specialNumbers) {
        if (isSpecial(num)) {
            std::cout << num << std::endl;
        }
    }
    return 0;
}
