```cpp
#include <iostream>
#include <vector>

bool isPrime(int n) {
    if(n <= 1) return false;
    if(n == 2) return true;
    if(n % 2 == 0) return false;
    for(int i = 3; i * i <= n; i += 2) {
        if(n % i == 0) return false;
    }
    return true;
}

bool satisfiesCondition(int n) {
    return isPrime(n) && isPrime(n + 2);
}

int main() {
    int count = 0;
    int number = 3;
    while(count < 8) {
        if(satisfiesCondition(number)) {
            std::cout << number << " ";
            count++;
            number += 2; // skip even numbers
        } else {
            number++;
        }
    }
    return 0;
}
```

