```cpp
#include <iostream>
using namespace std;

bool isPrime(int n) {
    if (n <= 1) return false;
    for (int i = 2; i * i <= n; i++)
        if (n % i == 0) return false;
    return true;
}

int nextPrime(int n) {
    int prime = n;
    bool found = false;
    while (!found) {
        prime++;
        if (isPrime(prime))
            found = true;
    }
    return prime;
}

int main() {
    int n = 10;
    int prime = 2;
    int sum = 0;
    for (int i = 0; i < n; i++) {
        if (i < 2) {
            cout << sum << ", ";
        } else {
            sum += prime;
            cout << sum << ", ";
            prime = nextPrime(prime);
        }
    }
    return 0;
}
