#include <iostream>

int main() {
    int n = 8; // Length of the sequence
    int a = 1, b = 0, c = 1;
    int next;

    for(int i = 0; i < n; i++) {
        if(i == 0) {
            std::cout << a << " ";
        } else if(i == 1) {
            std::cout << b << " ";
        } else if(i == 2) {
            std::cout << c << " ";
        } else {
            next = a + b + c;
            std::cout << next << " ";
            a = b;
            b = c;
            c = next;
        }
    }
    return 0;
}
