#include <iostream>
#include <vector>

int factorial(int n) {
    return (n == 0 || n == 1) ? 1 : n * factorial(n - 1);
}

bool isSpecial(int n) {
    int sum = 0, temp = n;
    while (temp > 0) {
        sum += factorial(temp % 10);
        temp /= 10;
    }
    return sum == n;
}

int main() {
    for (int i = 1; i <= 40585; ++i) {
        if (isSpecial(i)) {
            std::cout << i << std::endl;
        }
    }
    return 0;
}
