int main() {
    int n = 8; // Sequence length
    int a = 1, b = 0, c = 1, d; // Initial values
    std::cout << a << ", " << b << ", " << c; // Print initial values
    for(int i = 3; i < n; i++) {
        d = a + b + c; // Calculate next value
        std::cout << ", " << d; // Print next value
        a = b; // Shift values for the next iteration
        b = c;
        c = d;
    }
    return 0;
}
