```cpp
#include <iostream>
#include <vector>

bool isPrime(int n) {
    if (n <= 1) return false;
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) return false;
    }
    return true;
}

int main() {
    std::vector<int> sequence;
    for (int i = 2; sequence.size() < 8; i++) {
        if (isPrime(i) && isPrime(i + 2)) {
            sequence.push_back(i + 2);
        }
    }
    for (int num : sequence) {
        std::cout << num << " ";
    }
    return 0;
}
