```python
def look_and_say_sequence(n):
    result = "1"
    for _ in range(n - 1):
        current = result[0]
        count = 1
        temp_result = ""
        for char in result[1:]:
            if char == current:
                count += 1
            else:
                temp_result += str(count) + current
                current = char
                count = 1
        temp_result += str(count) + current
        result = temp_result
    return result

for i in range(1, 6):
    print(look_and_say_sequence(i))
