def sequence(n):
    primes = []
    i = 2
    while len(primes) < n*(n+1)//2:
        for j in range(2, int(i ** 0.5) + 1):
            if i % j == 0:
                break
        else:
            primes.append(i)
        i += 1
    result = [sum(primes[x*(x+1)//2:x*(x+1)//2+x+1]) for x in range(n)]
    return result

