```r
is_prime <- function(n) {
  if (n == 2) {
    return(TRUE)
  } else if (n < 2 || n %% 2 == 0) {
    return(FALSE)
  }
  for (i in 3:sqrt(n)) {
    if (n %% i == 0) {
      return(FALSE)
    }
  }
  return(TRUE)
}

n <- 2
count <- 0
while (count < 10) {
  if (is_prime(n)) {
    print(n)
    count <- count + 1
  }
  n <- n + 1
}
```

