```r
primeSeq <- function(L) {
  if (L >= 1) {
    primes = c(2)
    num = 3
    while (length(primes) < L) {
      if (all(num %% primes != 0)) {
        primes = c(primes, num)
      }
      num = num + 2
    }
    return(primes)
  } else {
    return(integer(0))
  }
}
primeSeq(10)
```

```r
produce_sequence <- function(n) {
  curr_seq <- "1"
  for (i in 2:n) {
    curr_seq <- gsub("((.)\\2*)", "\\1 ", curr_seq)
    curr_seq <- gsub(" ", "", sprintf("%s%s ", nchar(strsplit(curr_seq, " ")[[1]]), unlist(strsplit(curr_seq, " ")[[1]]))))
  }
  return(curr_seq)
}

# Producing the sequence
