```r
prime_seq <- function(n) {
  if (n == 1) {
    return(2)
  }
  primes <- c(2)
  count <- 1
  num <- 3
  while(count < n) {
    if(all(num %% primes != 0)) {
      primes <- c(primes, num)
      count <- count + 1
    }
    num <- num + 2
  }
  return(primes)
}

print(prime_seq(10))
```

```r
primes <- function(n) {
  if (n >= 2) {
    sieve <- rep(TRUE, n)
    sieve[1] <- FALSE
    for (i in 2:sqrt(n)) {
      if (sieve[i]) {
        sieve[seq(i^2, n, i)] <- FALSE
      }
    }
    return(which(sieve))
  } else {
    return(integer(0))
  }
}

n <- 30
prime_numbers <- primes(n)
print(prime_numbers)
```

