  if (n < 2 || n %% 2 == 0) {
    return(FALSE)
  }
  for (i in 3:sqrt(n)) {
    if (n %% i == 0) {
      return(FALSE)
    }
  }
  return(TRUE)
}

primes <- c()
n <- 2
while (length(primes) < 10) {
  if (is_prime(n)) {
    primes <- c(primes, n)
  }
  n <- n + 1
}
