produce_sequence <- function(n) {
  if (n == 1) return("1")
  prev_seq <- produce_sequence(n - 1)
  result <- ""
  count <- 1
  for (i in 2:nchar(prev_seq)) {
    if (substr(prev_seq, i, i) == substr(prev_seq, i-1, i-1)) {
      count <- count + 1
    } else {
      result <- paste0(result, count, substr(prev_seq, i-1, i-1))
      count <- 1
    }
  }
  result <- paste0(result, count, substr(prev_seq, nchar(prev_seq), nchar(prev_seq)))
  return(result)
}

