primes <- function(n) {
  if (n >= 1) {
    primes_vec <- 2:10000 # Generating a large vector to ensure we cover enough primes
    p <- 2:which(primes_vec == max(primes_vec))
    for (i in primes_vec) {
      p <- p[p == i | p %% i != 0]
      if (i >= sqrt(max(primes_vec))) break
    }
    return(p[1:n])
  } else {
    return(integer(0)) # Return an empty integer vector if n < 1
  }
}
