primes <- function(n) {
  if (n >= 1) {
    prime_numbers = 2
    count = 1
    num = 3
    while (count < n) {
      is_prime = TRUE
      for (i in 2:sqrt(num)) {
        if (num %% i == 0) {
          is_prime = FALSE
          break
        }
      }
      if (is_prime) {
        prime_numbers = c(prime_numbers, num)
        count = count + 1
      }
      num = num + 1
    }
    return(prime_numbers)
  } else {
    return(numeric(0))
  }
}

