function isPrime(num) {
  for (let i = 2, s = Math.sqrt(num); i <= s; i++)
    if (num % i === 0) return false;
  return num > 1;
}

function generatePrimes(n) {
  const primes = [];
  for (let num = 2; primes.length < n; num++) {
    if (isPrime(num)) {
      primes.push(num);
    }
  }
  return primes;
}

