function generateSequence(n) {
  let a = 1, b = 1, c = 1, d = 2, e = 3, seq = [];

  for (let i = 0; i < n; i++) {
    seq.push(a);
    let temp = e;
    e = d + e + a;
    a = b;
    b = c;
    c = d;
    d = temp;
  }

  return seq;
}

