function sequence(n) {
  if (n === 1) return 1;
  if (n === 2) return 2;

  let a = 1, b = 2, c;
  for (let i = 3; i <= n; i++) {
    c = (b * (2*i - 1) - a + (i - 1)) % 1000000;
    a = b;
    b = c;
  }
  return c;
}

