  let a = 2, b = 1, c = 3;
  let sequence = [a, b, c];
  for (let i = 3; i < n; i++) {
    let next = a + b + c;
    sequence.push(next);
    a = b;
    b = c;
    c = next;
  }
  return sequence;
}

console.log(generateSequence(10));
```

