function lookAndSay(n) {
    let result = ["1"];
    for (let i = 1; i < n; i++) {
        let current = result[i - 1];
        let tempResult = '';
        let count = 1;
        for (let j = 0; j < current.length; j++) {
            if (current[j] === current[j + 1]) {
                count++;
            } else {
                tempResult += count.toString() + current[j];
                count = 1;
            }
        }
        result.push(tempResult);
    }
    return result;
}

console.log(lookAndSay(5));
