function generateSequence(n) {
    let result = [];
    for (let i = 1; i <= n; i++) {
        if (i === 1) result.push(1);
        else if (i === 2) result.push(2);
        else if (i === 3) result.push(3);
        else if (i % 4 === 0) result.push(result[i - 2] + 2);
        else result.push(result[i - 2] + 3);
    }
    return result;
}

console.log(generateSequence(8));
```

