function sequence(n) {
    if (n === 1 || n === 2) return 0;
    if (n === 3) return 2;
    let a = 0, b = 0, c = 2, sum = 2;
    for (let i = 4; i <= n; i++) {
        sum += i - 1;
        let next = a + b + c + sum;
        a = b;
        b = c;
        c = next;
    }
    return c;
}

for (let i = 1; i <= 10; i++) {
    console.log(sequence(i));
}
