```javascript
function generateSequence() {
    let sequence = [];
    let primes = [];
    for (let number = 2; sequence.length < 10; number++) {
        let isPrime = true;
        for (let prime of primes) {
            if (number % prime === 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            primes.push(number);
            if (primes.length > 1) {
                sequence.push(primes[primes.length - 1] + primes[primes.length - 2]);
            }
        }
    }
    return sequence;
}

console.log(generateSequence());
```

```javascript
function factorial(n) {
    return n ? n * factorial(n - 1) : 1;
}

function sumOfFactorials(num) {
    return num.toString().split('').reduce((sum, digit) => sum + factorial(+digit), 0);
}

function findSequence() {
    let sequence = [];
    for (let i = 1; i < 100000; i++) {
        if (i === sumOfFactorials(i)) {
            sequence.push(i);
        }
    }
    return sequence;
}

console.log(findSequence());
